import csv
with open('inputs/eurostat/indicator_descriptions.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    rows = list(reader)

themes = {}
for row in rows:
    theme = row[2]
    if theme not in themes:
        themes[theme] = []
    themes[theme].append(row)

for theme in sorted(themes.keys()):
    print(f'=== {theme} ({len(themes[theme])} indicators) ===')
    for r in themes[theme]:
        print(f'  {r[0]} | {r[1][:80]} | {r[5]}')
